import{_ as e}from"./chunks/3abe179a9e21bac3cd1e1f62a7a17584.DdyjBE1Q.js";import{_ as r,c as t,a2 as o,o as i}from"./chunks/framework.BnrAgU0Y.js";const l="/bllm/assets/be07bc51db25d5fbb7c87e255c28b785.DJDhwins.png",n="/bllm/assets/973ba09f66aea1d7da0b2ad4e1b05392.C-iX8QDQ.png",m=JSON.parse('{"title":"将 Apify 集成到 Langflow 中","description":"将 Apify 集成到 Langflow 中","frontmatter":{"title":"将 Apify 集成到 Langflow 中","description":"将 Apify 集成到 Langflow 中","layout":"doc"},"headers":[],"relativePath":"langflow/integrations-apify.md","filePath":"langflow/integrations-apify.md"}'),p={name:"langflow/integrations-apify.md"};function s(f,a,c,h,A,d){return i(),t("div",null,a[0]||(a[0]=[o('<h1 id="将-apify-集成到-langflow-中" tabindex="-1">将 Apify 集成到 Langflow 中 <a class="header-anchor" href="#将-apify-集成到-langflow-中" aria-label="Permalink to &quot;将 Apify 集成到 Langflow 中&quot;">​</a></h1><p><a href="https://apify.com/" target="_blank" rel="noreferrer">Apify</a> 是一个网页抓取和数据提取平台。它提供了一个应用商店，内含超过三千个现成的云工具，称为 Actors。</p><p>Apify 组件允许您在您的流程中运行 Apify Actors，以完成以下任务：</p><ul><li>抓取网站并提取文本内容</li><li>抓取社交媒体平台，如 Instagram 和 Facebook</li><li>从 Google Maps 提取数据</li><li>将数据插入 PostgreSQL/MySQL/MSSQL 数据库</li><li>运行其他各种自动化任务</li></ul><p>关于 Apify 的更多信息：</p><ul><li><a href="https://apify.com/" target="_blank" rel="noreferrer">官方网站</a></li><li><a href="https://apify.com/store" target="_blank" rel="noreferrer">Apify Actor 商店</a></li><li><a href="https://whitepaper.actor/" target="_blank" rel="noreferrer">Actor 白皮书</a></li></ul><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><p>您需要一个 <strong>Apify API token</strong>（Apify API令牌）。您可以在 <a href="https://apify.com/" target="_blank" rel="noreferrer">Apify</a> 上创建一个免费账户，并在 Apify 控制台中生成您的 API 密钥。<a href="https://docs.apify.com/platform/integrations/api" target="_blank" rel="noreferrer">在此获取免费 API 密钥</a>。</p><p>在所有需要密钥的组件中输入该密钥到 <em>Apify Token</em> 字段。</p><h2 id="示例流程" tabindex="-1">示例流程 <a class="header-anchor" href="#示例流程" aria-label="Permalink to &quot;示例流程&quot;">​</a></h2><h3 id="提取网站文本内容为-markdown-格式" tabindex="-1">提取网站文本内容为 Markdown 格式 <a class="header-anchor" href="#提取网站文本内容为-markdown-格式" aria-label="Permalink to &quot;提取网站文本内容为 Markdown 格式&quot;">​</a></h3><p><img src="'+e+'" alt="Apify Flow - Website Content Crawler"></p><h3 id="使用代理分析和处理网站内容" tabindex="-1">使用代理分析和处理网站内容 <a class="header-anchor" href="#使用代理分析和处理网站内容" aria-label="Permalink to &quot;使用代理分析和处理网站内容&quot;">​</a></h3><p><img src="'+l+'" alt="Apify Agent Flow - Simple"></p><h3 id="search-and-analyze-social-media-profiles-with-an-agent" tabindex="-1">Search and analyze social media profiles with an Agent <a class="header-anchor" href="#search-and-analyze-social-media-profiles-with-an-agent" aria-label="Permalink to &quot;Search and analyze social media profiles with an Agent&quot;">​</a></h3><p>代理搜索和分析社交媒体档案</p><p><img src="'+n+'" alt="Apify Agent Flow"></p><h2 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h2><h3 id="apify-actors" tabindex="-1">Apify Actors <a class="header-anchor" href="#apify-actors" aria-label="Permalink to &quot;Apify Actors&quot;">​</a></h3><p>此组件允许您在流程中运行 Apify Actors（演员）。它可以通过提供运行输入手动使用，或者作为 AI Agent（人工智能代理）的工具集成使用。当与 AI Agent 一起使用时，代理可以利用 Apify Actors 执行各种任务。</p><ul><li><p><strong>输入</strong>：</p><ul><li>Apify Token: 您的 API 密钥。</li><li>Actor（演员）: 要运行的 Apify Actor。示例：<code>apify/website-content-crawler</code>。</li><li>Run Input: 用于配置 Actor 运行的 JSON 输入。</li></ul></li><li><p><strong>输出</strong>：</p><ul><li>Actor Run Result: 包含演员运行输出的 JSON 响应。</li></ul></li></ul><h2 id="如何在-langflow-中使用-apify-actors" tabindex="-1">如何在 Langflow 中使用 Apify Actors <a class="header-anchor" href="#如何在-langflow-中使用-apify-actors" aria-label="Permalink to &quot;如何在 Langflow 中使用 Apify Actors&quot;">​</a></h2><p>首先，你需要从 <a href="https://apify.com/store" target="_blank" rel="noreferrer">Apify Actor Store</a> 中选择一个你想要在流程中使用的 Actor。接着，创建 <strong>Apify Actors</strong> 组件，并输入你的 Apify API 令牌和 Actor ID。你可以在 Apify Actor Store 中找到 Actor ID，例如，<a href="https://apify.com/apify/website-content-crawler" target="_blank" rel="noreferrer">Website Content Crawler</a> 的 Actor ID 是 <code>apify/website-content-crawler</code>。现在你可以将 <strong>Tool</strong> 输出连接到一个 AI Agent，或者手动配置 Run input 的 JSON 并运行组件，以从 <strong>Output Data</strong> 中检索数据。Run input 示例可以从 Apify Actor Store 的 Actor 详情页面获得。在输入架构部分查看 <a href="https://apify.com/apify/website-content-crawler/input-schema" target="_blank" rel="noreferrer">JSON 示例</a>。</p>',23)]))}const b=r(p,[["render",s]]);export{m as __pageData,b as default};
